"""Working, distinct GUI starters. These produce web documents, not native executables."""

def template_html(template, rows, columns):
    if template not in ('grid','sidebar','master-detail','studio'):
        raise ValueError('Choose a known GUI template.')
    count=rows*columns
    cards=''.join(f'<section class="card"><h2>Panel {i+1:02}</h2><p>Choose a feature for this panel.</p><button onclick="this.nextElementSibling.hidden=!this.nextElementSibling.hidden">Explore panel</button><p hidden>Panel {i+1} is ready.</p></section>' for i in range(count))
    sidebar=''
    content=f'<div class="grid">{cards}</div>'
    script=''
    if template=='sidebar':
        sidebar='''<nav aria-label="Application navigation"><h2>Workspace</h2><button onclick="showView('overview',this)" aria-current="page">Overview</button><button onclick="showView('library',this)">Library</button><button onclick="showView('settings',this)">Settings</button></nav>'''
        content=f'''<section id="overview" class="view"><div class="grid">{cards}</div></section><section id="library" class="view" hidden><h2>Library</h2><input id="librarySearch" aria-label="Search library" placeholder="Search saved items" oninput="filterLibrary(this.value)"><ul id="libraryItems"><li>Design notes</li><li>Project assets</li><li>Release checklist</li></ul></section><section id="settings" class="view" hidden><h2>Settings</h2><label>Workspace name <input id="workspaceName" value="Your new application"></label><button onclick="document.querySelector('h1').textContent=document.getElementById('workspaceName').value">Apply name</button></section>'''
        script="""function showView(id,button){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('nav button').forEach(b=>b.removeAttribute('aria-current'));button.setAttribute('aria-current','page')}function filterLibrary(q){document.querySelectorAll('#libraryItems li').forEach(li=>li.hidden=!li.textContent.toLowerCase().includes(q.toLowerCase()))}"""
    elif template=='master-detail':
        records=''.join(f'<button class="record" data-record="{i+1}" onclick="selectRecord({i+1},this)">Record {i+1:02}</button>' for i in range(max(2,count)))
        content=f'''<div class="master-detail"><aside><h2>Records</h2><input aria-label="Filter records" placeholder="Filter records" oninput="filterRecords(this.value)"><div id="recordList">{records}</div></aside><section class="detail" aria-live="polite"><small>SELECTED RECORD</small><h2 id="recordTitle">Record 01</h2><p id="recordDescription">Inspect a record from the list.</p><label>Notes<textarea id="recordNotes" placeholder="Add a note"></textarea></label><button onclick="saveNote()">Save note</button><p id="recordStatus" role="status"></p></section></div>'''
        script="""let selected=1;const notes={};function selectRecord(id,button){selected=id;document.getElementById('recordTitle').textContent='Record '+String(id).padStart(2,'0');document.getElementById('recordDescription').textContent='Details for record '+id;document.getElementById('recordNotes').value=notes[id]||'';document.getElementById('recordStatus').textContent='';document.querySelectorAll('.record').forEach(b=>b.classList.toggle('selected',b===button))}function filterRecords(q){document.querySelectorAll('.record').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q.toLowerCase()))}function saveNote(){notes[selected]=document.getElementById('recordNotes').value;document.getElementById('recordStatus').textContent='Note saved for record '+selected}"""
    elif template=='studio':
        content='''<div class="studio"><aside><h2>Explorer</h2><button onclick="openDocument('Welcome')">Welcome.txt</button><button onclick="openDocument('Notes')">Notes.txt</button><button onclick="openDocument('Ideas')">Ideas.txt</button></aside><section class="canvas"><h2 id="documentTitle">Welcome.txt</h2><textarea id="documentEditor" aria-label="Document editor" oninput="updateInspector()">Welcome to your developer workspace.</textarea><button onclick="previewDocument()">Preview document</button><pre id="documentPreview" hidden></pre></section><aside><h2>Inspector</h2><p>Characters: <strong id="characterCount">0</strong></p><p id="documentStatus" role="status">Ready</p></aside></div>'''
        script="""let current='Welcome';const documents={Welcome:'Welcome to your developer workspace.',Notes:'Your project notes.',Ideas:'Your next idea starts here.'};function openDocument(name){documents[current]=document.getElementById('documentEditor').value;current=name;document.getElementById('documentTitle').textContent=name+'.txt';document.getElementById('documentEditor').value=documents[name];document.getElementById('documentPreview').hidden=true;updateInspector()}function updateInspector(){document.getElementById('characterCount').textContent=document.getElementById('documentEditor').value.length;document.getElementById('documentStatus').textContent=current+' selected'}function previewDocument(){const p=document.getElementById('documentPreview');p.textContent=document.getElementById('documentEditor').value;p.hidden=false}updateInspector();"""
    style='''*{box-sizing:border-box}body{margin:0;background:#f5f5f0;color:#24382d;font:15px system-ui;display:flex;min-height:100vh}nav{width:190px;padding:26px;background:#e8ece2;flex:none}nav button{display:block;margin:12px 0}main{flex:1;min-width:0;padding:28px}header{display:flex;gap:15px;justify-content:space-between;align-items:center;margin-bottom:26px}h1{font-size:28px;margin:4px 0}small{color:#708071}.grid{display:grid;grid-template-columns:repeat(COLUMNS,minmax(0,1fr));gap:14px}.card,.detail,.canvas{background:white;border:1px solid #dce2d7;padding:20px;border-radius:10px}.card{min-height:150px}h2{font-size:16px}button{background:#294f3d;color:white;border:0;border-radius:6px;padding:9px 12px;cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #d2ad55;outline-offset:3px}button[aria-current],.record.selected{background:#52785c}input,textarea{font:inherit;border:1px solid #ced9cc;border-radius:5px;padding:9px;max-width:100%}label{display:flex;flex-direction:column;gap:8px;margin:15px 0}.master-detail{display:grid;grid-template-columns:minmax(160px,1fr) minmax(260px,2fr);gap:18px}.record{display:block;width:100%;margin:9px 0;text-align:left}.detail textarea{min-height:130px}.studio{display:grid;grid-template-columns:160px minmax(250px,1fr) 170px;gap:16px}.studio aside{background:#e8ece2;padding:15px;border-radius:8px}.studio aside button{display:block;margin:9px 0;width:100%;text-align:left}.canvas textarea{width:100%;min-height:240px}.canvas pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef2e8;padding:15px}html.dark{filter:invert(.85)}[hidden]{display:none!important}@media(max-width:700px){.grid,.master-detail,.studio{grid-template-columns:1fr}nav{width:145px}main{padding:18px}}'''.replace('COLUMNS',str(columns))
    return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New application</title><style>{style}</style><body data-template="{template}">{sidebar}<main><header><div><small>BUILT WITH HEXWISE</small><h1>Your new application</h1></div><button onclick="document.documentElement.classList.toggle('dark')">Toggle theme</button></header>{content}</main><script>{script}</script></body></html>'''.encode()
